import { describe, expect, test } from "bun:test";
import { trainPolicy, type Git } from "../../scripts/gate.ts";

const at = (out: string, ok = true): Git => () => ({ ok, out });
const policy = (train: unknown) => at(JSON.stringify({ train }));

describe("trainPolicy", () => {
  test("refuses a malformed or unsafe train block", () => {
    expect(trainPolicy(policy({ record_artifact: "rec", full_gate_check: "gstack-evals/full-gate" }), "c")).toEqual({ record_artifact: "rec", full_gate_check: "gstack-evals/full-gate" });
    expect(trainPolicy(at("{"), "c")).toBeNull();
    expect(trainPolicy(at("", false), "c")).toBeNull();
    expect(trainPolicy(policy(null), "c")).toBeNull();
    expect(trainPolicy(policy({ record_artifact: "rec" }), "c")).toBeNull();
    expect(trainPolicy(policy({ record_artifact: "rec\nmode=train", full_gate_check: "x" }), "c")).toBeNull();
    expect(trainPolicy(policy({ record_artifact: "rec", full_gate_check: "a b" }), "c")).toBeNull();
    expect(trainPolicy(policy({ record_artifact: "r".repeat(101), full_gate_check: "x" }), "c")).toBeNull();
  });
});
